FUNCTION_BLOCK FB_Biogas_DigesterBufferScrubber
(*
========================================================================================================================
  PROJECT      : MEGA-SCALE ANAEROBIC DIGESTION BIOGAS FACILITY (12,000 m3 THERMOPHILIC PRIMARY DIGESTION)
  SUBSYSTEM    : DIGESTER pH BUFFER SLURRY DOSING & BIOLOGICAL TRICKLING FILTER H2S DESULFURIZATION
  DESIGNATION  : SIL-2 / CLASS I DIV 2 DUAL PROCESS CPS AUTOMATION CONTROLLER
  SPECIFICATION: IEC 61131-3 3RD EDITION / ISA-18.2 ALARM MANAGEMENT / ISA-88 CONTINUOUS STATE MACHINE
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  THEORETICAL AND CYBER-PHYSICAL FORMULATION:
    1. ANAEROBIC THERMOPHILIC BUFFERING DYNAMICS (pH & VFA-TIC EQUILIBRIUM):
       The methanogenesis phase in thermophilic anaerobic digestion (operating strictly at 52.0 - 55.0 deg C) is
       extremely vulnerable to volatile fatty acid (VFA) accumulation (acetic, propionic, butyric acids). If total
       alkalinity (TIC) drops below buffering capacity, a sudden drop in pH (<6.8) triggers rapid methanogen inhibition,
       often leading to irreversible digester souring.
       This block utilizes a discrete state-space model approximation:
           x_k+1 = A * x_k + B * u_k + E * d_k
           y_k   = C * x_k + D * u_k
       where x = [delta_pH, d(VFA)/dt, delta_H2S_gas, biofilm_viability]^T.
       Slurry dosing (lime / sodium bicarbonate saturated suspension) is modulated via predictive error feedback
       and feedforward organic loading compensation.

    2. BIOLOGICAL H2S DESULFURIZATION BIO-REACTION KINETICS:
       Biological trickling filter (BTF) scrubbers cultivate autotrophic sulfur-oxidizing bacteria (Thiobacillus /
       Acidithiobacillus strains) adhering to structured polyurethane/polypropylene media:
           H2S(g) <-> H2S(aq)                                    (Gas-liquid absorption mass transfer)
           2 H2S + O2 -> 2 S^0 + 2 H2O                          (Partial oxidation, delta G = -443 kJ/mol)
           2 S^0 + 3 O2 + 2 H2O -> 2 H2SO4                      (Complete oxidation to sulfuric acid)
       Micro-aeration stoichiometry is controlled dynamically. To maintain the non-explosive atmosphere in raw biogas,
       oxygen enrichment must never exceed 1.5% to 2.0% v/v (safe margin below Lower Explosive Limit LEL).

    3. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING:
       Three industrial differential pH sensors with pressurized gel electrolyte are continuously monitored.
       The voting core detects drift (>0.25 pH divergence), individual electrode poisoning, or reference junction
       fouling, dynamically transitioning from 2oo3 -> 2oo2 -> 1oo1 -> degraded failsafe.

    4. MULTI-LAYER GRACEFUL DEGRADATION & ALARM TREES:
       ISA-18.2 compliant priority alarm shelving, first-out emergency vent interlocking, and automatic stream diverter
       to the flare stack upon digester headspace overpressure or biological desulfurizer flooding.
========================================================================================================================
*)

VAR_INPUT
    (* --- System Safety and Mode Permissives --- *)
    bMasterEnable               : BOOL;     (* Master process train permissive signal [TRUE=Run Permitted] *)
    bSafetyEStopOk              : BOOL;     (* Hardwired SIL-2 emergency stop safety loop [TRUE=Healthy, FALSE=Tripped] *)
    bAutoModeSelect             : BOOL;     (* Supervisory mode selector: TRUE = Closed-Loop MPC, FALSE = Safe Coordinated Manual *)

    (* --- Process Analytical Measurements & Primary Instrumentation --- *)
    rDigesterPh_Sensor1         : REAL;     (* Redundant pH channel 1 primary electrode measurement [pH] (0.00 .. 14.00) *)
    rDigesterPh_Sensor2         : REAL;     (* Redundant pH channel 2 secondary electrode measurement [pH] (0.00 .. 14.00) *)
    rDigesterPh_Sensor3         : REAL;     (* Redundant pH channel 3 tertiary electrode measurement [pH] (0.00 .. 14.00) *)
    rDigesterTemp_DegC          : REAL;     (* Thermophilic digester core bulk slurry temperature [deg C] (50.0 .. 60.0) *)
    rBiogasInflow_m3h           : REAL;     (* Raw biogas volumetric flow rate entering BTF desulfurizer [m3/h] (0 .. 5000) *)
    rBiogasInletPressure_mbar   : REAL;     (* Anaerobic digester dome headspace gauge pressure [mbar] (-5.0 .. 50.0) *)
    rH2S_RawGas_ppm             : REAL;     (* Raw inlet biogas H2S concentration from optical analyzer [ppm] (100 .. 10000) *)
    rH2S_CleanGas_ppm           : REAL;     (* Scrubber outlet desulfurized biogas H2S concentration [ppm] (Target < 50 ppm) *)
    rNutrientTrickleFlow_Lh     : REAL;     (* Biological scrubber packing wash liquid circulation flow rate [L/h] (0 .. 15000) *)
    rSlurryTankLevel_Pct        : REAL;     (* Alkaline buffer slurry storage tank hydrostatic level [%] (0.0 .. 100.0) *)
    rVolatileFattyAcids_mgL     : REAL;     (* Real-time titrimetric/NIR volatile fatty acid concentration [mg/L acetic eq] *)
    bScrubberSumpHighLvl        : BOOL;     (* Desulfurization bio-sump emergency high liquid level discrete float (LSHH) *)
    bAirInjectionPermissive     : BOOL;     (* Hazardous area micro-aeration Stoichiometric O2 injection safety permissive *)
END_VAR

VAR_OUTPUT
    (* --- Actuation Commands & Setpoints --- *)
    bSystemReady                : BOOL;     (* Overall automation engine operational readiness indicator *)
    bDegradedModeActive         : BOOL;     (* Operating in degraded sensor or process fallback mode *)
    rBufferSlurryDoseRate_Lh    : REAL;     (* Modulated positive displacement buffer slurry dosing pump command [L/h] *)
    rAirInjectionFlow_Nm3h      : REAL;     (* Stoichiometric micro-aeration air injection control valve setpoint [Nm3/h] *)
    rNutrientCircPumpSpeed_Pct  : REAL;     (* Biological trickling bed nutrient recirculation pump VFD command [%] (0..100) *)
    rBiogasBypassValve_Pct      : REAL;     (* Emergency biogas bypass / emergency safety flare diverter valve [%] (0..100) *)

    (* --- Diagnostics, Status Words and Validated Process Values --- *)
    wAlarmWord                  : WORD;     (* ISA-18.2 packed alarm status register (Bit0=Critical, Bit1=TMR, etc.) *)
    wSystemStatusWord           : WORD;     (* Diagnostic and state machine status indicator word *)
    rVotedDigesterPh            : REAL;     (* Validated 2oo3 TMR resolved digester pH process value [pH] *)
    rEffectiveH2SRemovalEff_Pct : REAL;     (* Calculated real-time biological scrubber desulfurization efficiency [%] *)
END_VAR

VAR
    (* --- State Machine Registers --- *)
    iState                      : INT := 0; (* Active operational state index *)
    iPreviousState              : INT := 0; (* Historical state transition tracker *)

    (* --- Triple Modular Redundancy (2oo3) Validation Registers --- *)
    bSensor1_Valid              : BOOL := TRUE;
    bSensor2_Valid              : BOOL := TRUE;
    bSensor3_Valid              : BOOL := TRUE;
    iHealthySensorCount         : INT  := 3;
    rDelta12                    : REAL := 0.0;
    rDelta23                    : REAL := 0.0;
    rDelta31                    : REAL := 0.0;
    rTmrToleranceLimit          : REAL := 0.25; (* Maximum permissible inter-electrode pH divergence [pH] *)

    (* --- State-Space Discrete Model Representation (Sampling Period dt = 1.0 s) --- *)
    (* State Vector x:
         x[0] = delta_pH (deviation from target 7.35)
         x[1] = d(VFA)/dt (volatile fatty acid accumulation rate [mg/L/s])
         x[2] = delta_H2S_clean (outlet concentration deviation from target 40 ppm)
         x[3] = normalized biofilm sulfur-oxidizing metabolic activity [0.0 .. 1.2]
    *)
    rState_x1_PhErr             : REAL := 0.0;
    rState_x2_VfaTrend          : REAL := 0.0;
    rState_x3_H2SErr            : REAL := 0.0;
    rState_x4_BioHealth         : REAL := 1.0;

    (* System Dynamics Coefficients (Linearized Discretized Plant Matrices A & B) *)
    rA11 : REAL := 0.9420;  rA12 : REAL := -0.0015; rB11 : REAL := 0.0048; (* Slurry pump authority on pH *)
    rA21 : REAL := 0.0000;  rA22 : REAL := 0.8850;  rB12 : REAL := 0.0000;
    rA33 : REAL := 0.7300;  rA34 : REAL := -0.1650; rB22 : REAL := -0.0680; (* Air injection authority on clean H2S *)
    rA43 : REAL := 0.0008;  rA44 : REAL := 0.9960;  

    (* Model Predictive Horizon Accumulators & Target Parameters *)
    rPhSetpoint                 : REAL := 7.35; (* Target thermophilic methanogenic equilibrium pH *)
    rH2S_Setpoint_ppm           : REAL := 40.0; (* Maximum regulatory combustion engine clean gas limit [ppm] *)
    rVfaPrevious                : REAL := 2500.0;
    rPredPhHorizonErr           : REAL := 0.0;
    rPredH2SHorizonErr          : REAL := 0.0;

    (* Signal Filtering & Conditioning Accumulators *)
    rBiogasFlow_Filt            : REAL := 0.0;
    rH2SClean_Filt              : REAL := 0.0;
    rDigesterPressure_Filt      : REAL := 0.0;

    (* System Timers & Hardware Watchdogs *)
    tonStartupDelay             : TON;
    tonSensorFaultDebounce      : TON;
    tonAcidificationPersistence : TON;
    tonStateTimer               : TON;

    (* Continuous Diagnostic Metrics *)
    udiCycleCounter             : UDINT := 0;
    udiAcidificationEventTotal  : UDINT := 0;
    rCumulativeSlurryDosed_L    : REAL := 0.0;
END_VAR

(*
========================================================================================================================
  CYCLIC EXECUTION ROUTINE
========================================================================================================================
*)

udiCycleCounter := udiCycleCounter + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: CRITICAL HARDWIRED SAFETY INTERLOCKS & FIRST-OUT TRIP LATCHING
   --------------------------------------------------------------------------------------------------------------------- *)
IF NOT bSafetyEStopOk THEN
    (* Fail-Safe Deterministic Shutdown Actions *)
    bSystemReady                := FALSE;
    bDegradedModeActive         := FALSE;
    rBufferSlurryDoseRate_Lh    := 0.0;
    rAirInjectionFlow_Nm3h      := 0.0;
    rNutrientCircPumpSpeed_Pct  := 0.0;

    (* Relieve digester dome pressure to emergency flare if high, otherwise isolate *)
    IF rBiogasInletPressure_mbar > 20.0 THEN
        rBiogasBypassValve_Pct  := 100.0; (* Divert biogas to flare *)
    ELSE
        rBiogasBypassValve_Pct  := 0.0;
    END_IF;

    wAlarmWord.0                := TRUE;  (* Emergency Trip E-Stop Bit *)
    wSystemStatusWord           := 16#F000;
    iState                      := 99;    (* Direct to emergency trip state *)
    RETURN;
END_IF;

wAlarmWord.0 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ALGORITHM
   --------------------------------------------------------------------------------------------------------------------- *)
(* Step 2.1: Electrode Valid Range Boundaries [pH 2.00 to 12.00] *)
bSensor1_Valid := (rDigesterPh_Sensor1 >= 2.00) AND (rDigesterPh_Sensor1 <= 12.00);
bSensor2_Valid := (rDigesterPh_Sensor2 >= 2.00) AND (rDigesterPh_Sensor2 <= 12.00);
bSensor3_Valid := (rDigesterPh_Sensor3 >= 2.00) AND (rDigesterPh_Sensor3 <= 12.00);

(* Step 2.2: Compute Cross-Electrode Discrepancies *)
rDelta12 := ABS(rDigesterPh_Sensor1 - rDigesterPh_Sensor2);
rDelta23 := ABS(rDigesterPh_Sensor2 - rDigesterPh_Sensor3);
rDelta31 := ABS(rDigesterPh_Sensor3 - rDigesterPh_Sensor1);

(* Step 2.3: Determine Consensus and Isolate Faulty Channel *)
IF bSensor1_Valid AND bSensor2_Valid AND bSensor3_Valid THEN
    IF (rDelta12 <= rTmrToleranceLimit) AND (rDelta23 <= rTmrToleranceLimit) AND (rDelta31 <= rTmrToleranceLimit) THEN
        (* All three electrodes within tight tolerance - Complete 2oo3 consensus *)
        rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor2 + rDigesterPh_Sensor3) / 3.0;
        iHealthySensorCount := 3;
        wAlarmWord.2        := FALSE; (* TMR Warning clear *)
    ELSIF (rDelta12 <= rTmrToleranceLimit) AND (rDelta23 > rTmrToleranceLimit) AND (rDelta31 > rTmrToleranceLimit) THEN
        (* Sensor 3 drifting out of tolerance: Reject Sensor 3, vote 1 and 2 *)
        rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor2) / 2.0;
        bSensor3_Valid      := FALSE;
        iHealthySensorCount := 2;
        wAlarmWord.2        := TRUE;  (* Sensor 3 divergence alarm *)
    ELSIF (rDelta23 <= rTmrToleranceLimit) AND (rDelta12 > rTmrToleranceLimit) AND (rDelta31 > rTmrToleranceLimit) THEN
        (* Sensor 1 drifting out of tolerance: Reject Sensor 1, vote 2 and 3 *)
        rVotedDigesterPh    := (rDigesterPh_Sensor2 + rDigesterPh_Sensor3) / 2.0;
        bSensor1_Valid      := FALSE;
        iHealthySensorCount := 2;
        wAlarmWord.2        := TRUE;  (* Sensor 1 divergence alarm *)
    ELSIF (rDelta31 <= rTmrToleranceLimit) AND (rDelta12 > rTmrToleranceLimit) AND (rDelta23 > rTmrToleranceLimit) THEN
        (* Sensor 2 drifting out of tolerance: Reject Sensor 2, vote 1 and 3 *)
        rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor3) / 2.0;
        bSensor2_Valid      := FALSE;
        iHealthySensorCount := 2;
        wAlarmWord.2        := TRUE;  (* Sensor 2 divergence alarm *)
    ELSE
        (* Total TMR Incoherence: Divergence across all channels *)
        rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor2 + rDigesterPh_Sensor3) / 3.0;
        iHealthySensorCount := 1;
        wAlarmWord.2        := TRUE;
        wAlarmWord.3        := TRUE;  (* Severe TMR Incoherence Fault *)
    END_IF;
ELSIF bSensor1_Valid AND bSensor2_Valid THEN
    rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor2) / 2.0;
    iHealthySensorCount := 2;
    wAlarmWord.2        := TRUE;
ELSIF bSensor2_Valid AND bSensor3_Valid THEN
    rVotedDigesterPh    := (rDigesterPh_Sensor2 + rDigesterPh_Sensor3) / 2.0;
    iHealthySensorCount := 2;
    wAlarmWord.2        := TRUE;
ELSIF bSensor1_Valid AND bSensor3_Valid THEN
    rVotedDigesterPh    := (rDigesterPh_Sensor1 + rDigesterPh_Sensor3) / 2.0;
    iHealthySensorCount := 2;
    wAlarmWord.2        := TRUE;
ELSIF bSensor1_Valid THEN
    rVotedDigesterPh    := rDigesterPh_Sensor1;
    iHealthySensorCount := 1;
    wAlarmWord.3        := TRUE;
ELSIF bSensor2_Valid THEN
    rVotedDigesterPh    := rDigesterPh_Sensor2;
    iHealthySensorCount := 1;
    wAlarmWord.3        := TRUE;
ELSIF bSensor3_Valid THEN
    rVotedDigesterPh    := rDigesterPh_Sensor3;
    iHealthySensorCount := 1;
    wAlarmWord.3        := TRUE;
ELSE
    (* Total Sensor Loss: Safe default pH 7.00 with critical alarm *)
    rVotedDigesterPh    := 7.00;
    iHealthySensorCount := 0;
    wAlarmWord.3        := TRUE;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: PROCESS VARIABLE FILTERING & MASS TRANSFER CALCULATIONS
   --------------------------------------------------------------------------------------------------------------------- *)
(* First-order digital low-pass filtering on dynamic gas flows and pressures *)
rBiogasFlow_Filt       := (rBiogasFlow_Filt * 0.70) + (rBiogasInflow_m3h * 0.30);
rH2SClean_Filt         := (rH2SClean_Filt * 0.75) + (rH2S_CleanGas_ppm * 0.25);
rDigesterPressure_Filt := (rDigesterPressure_Filt * 0.80) + (rBiogasInletPressure_mbar * 0.20);

(* Real-Time Biological Desulfurization Efficiency [%] *)
IF rH2S_RawGas_ppm > 15.0 THEN
    rEffectiveH2SRemovalEff_Pct := ((rH2S_RawGas_ppm - rH2SClean_Filt) / rH2S_RawGas_ppm) * 100.0;
    IF rEffectiveH2SRemovalEff_Pct < 0.0 THEN
        rEffectiveH2SRemovalEff_Pct := 0.0;
    ELSIF rEffectiveH2SRemovalEff_Pct > 99.9 THEN
        rEffectiveH2SRemovalEff_Pct := 99.9;
    END_IF;
ELSE
    rEffectiveH2SRemovalEff_Pct := 100.0;
END_IF;

(* Volatile Fatty Acid derivative trend [mg/L/cycle] *)
rState_x2_VfaTrend := rVolatileFattyAcids_mgL - rVfaPrevious;
rVfaPrevious       := rVolatileFattyAcids_mgL;

(* State tracking deviations *)
rState_x1_PhErr  := rPhSetpoint - rVotedDigesterPh;        (* Positive when digester acidifies *)
rState_x3_H2SErr := rH2SClean_Filt - rH2S_Setpoint_ppm;    (* Positive when outlet H2S exceeds threshold *)

(* Thermophilic Arrhenius temperature scaling on bio-catalytic kinetics (Optimal at 54.0 deg C) *)
IF (rDigesterTemp_DegC >= 50.0) AND (rDigesterTemp_DegC <= 58.0) THEN
    rState_x4_BioHealth := 1.0 - (ABS(rDigesterTemp_DegC - 54.0) * 0.035);
ELSE
    rState_x4_BioHealth := 0.45; (* Biofilm stress / methanogen kinetic inhibition *)
END_IF;

(* One-step receding horizon error projection *)
rPredPhHorizonErr  := (rA11 * rState_x1_PhErr) + (rA12 * rState_x2_VfaTrend);
rPredH2SHorizonErr := (rA33 * rState_x3_H2SErr) + (rA34 * rState_x4_BioHealth);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: SEQUENTIAL FINITE STATE MACHINE (ISA-88 MODULAR STATES)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_INIT_DIAGNOSTICS: Pre-start system verification *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        rBufferSlurryDoseRate_Lh    := 0.0;
        rAirInjectionFlow_Nm3h      := 0.0;
        rNutrientCircPumpSpeed_Pct  := 25.0; (* Base wetting flow to prevent media desiccation *)
        rBiogasBypassValve_Pct      := 0.0;
        wSystemStatusWord           := 16#0001;

        tonStartupDelay(IN := bMasterEnable, PT := T#8S);
        IF tonStartupDelay.Q THEN
            tonStartupDelay(IN := FALSE);
            IF (rSlurryTankLevel_Pct >= 12.0) AND (iHealthySensorCount >= 2) THEN
                iState := 10; (* Advance to Standby Purge *)
            ELSE
                wAlarmWord.4 := TRUE; (* Insufficient chemical or sensor unavailability *)
            END_IF;
        END_IF;

    10: (* STATE_STANDBY_PURGE: Packing media irrigation baseline *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := FALSE;
        rNutrientCircPumpSpeed_Pct  := 40.0;
        rBufferSlurryDoseRate_Lh    := 0.0;
        rAirInjectionFlow_Nm3h      := 0.0;
        rBiogasBypassValve_Pct      := 0.0;
        wSystemStatusWord           := 16#0010;

        IF bMasterEnable AND bAutoModeSelect THEN
            iState := 20; (* Engage Automated Model Predictive Control *)
        ELSIF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE_NORMAL_TMR_MPC_ACTIVE: Optimal Closed-Loop Dual-System Regulation *)
        bSystemReady        := TRUE;
        bDegradedModeActive := (iHealthySensorCount < 3);
        wSystemStatusWord   := 16#0020;

        (* Sub-Loop A: pH Buffer Slurry Dosing MPC Algorithm *)
        IF (rState_x1_PhErr > 0.02) OR (rVolatileFattyAcids_mgL > 3000.0) THEN
            (* Acidification detected: Calculate predictive dosing requirement *)
            rBufferSlurryDoseRate_Lh := (rPredPhHorizonErr * 520.0) + (rState_x2_VfaTrend * 0.15) 
                                       + ((rVolatileFattyAcids_mgL - 2500.0) * 0.08);
            (* Anti-cavitation and structural bounds *)
            IF rBufferSlurryDoseRate_Lh > 850.0 THEN
                rBufferSlurryDoseRate_Lh := 850.0; (* Pump capacity ceiling [L/h] *)
            ELSIF rBufferSlurryDoseRate_Lh < 18.0 THEN
                rBufferSlurryDoseRate_Lh := 18.0;  (* Anti-settling line scour velocity *)
            END_IF;
        ELSE
            (* Digester alkaline or balanced: Inactive slurry dosing *)
            rBufferSlurryDoseRate_Lh := 0.0;
        END_IF;

        (* Sub-Loop B: Stoichiometric Micro-Aeration Biological H2S Scrubbing *)
        IF bAirInjectionPermissive AND (rH2S_RawGas_ppm > 40.0) THEN
            (* Stoichiometric air demand: 2.06 Nm3 air per m3 pure H2S consumed with safety factor *)
            rAirInjectionFlow_Nm3h := (rBiogasFlow_Filt * rH2S_RawGas_ppm * 0.000001 * 2.06 * 1.30)
                                     + (rPredH2SHorizonErr * 0.05);
            (* Atmospheric air capping to guarantee <1.5% O2 in biogas *)
            IF rAirInjectionFlow_Nm3h > 125.0 THEN
                rAirInjectionFlow_Nm3h := 125.0;
            ELSIF rAirInjectionFlow_Nm3h < 1.5 THEN
                rAirInjectionFlow_Nm3h := 1.5;
            END_IF;
        ELSE
            rAirInjectionFlow_Nm3h := 0.0;
        END_IF;

        (* Sub-Loop C: Packing media wetting irrigation rate *)
        rNutrientCircPumpSpeed_Pct := 45.0 + ((rBiogasFlow_Filt / 5000.0) * 35.0) + (rH2SClean_Filt * 0.15);
        IF rNutrientCircPumpSpeed_Pct > 100.0 THEN
            rNutrientCircPumpSpeed_Pct := 100.0;
        END_IF;

        rBiogasBypassValve_Pct := 0.0;
        rCumulativeSlurryDosed_L := rCumulativeSlurryDosed_L + (rBufferSlurryDoseRate_Lh / 3600.0);

        (* Dynamic state transitions *)
        IF (rVolatileFattyAcids_mgL > 4200.0) OR (rVotedDigesterPh < 6.85) THEN
            iState := 30; (* Acidification surge event *)
        ELSIF rH2SClean_Filt > 220.0 THEN
            iState := 40; (* Scrubbing breakthrough event *)
        ELSIF (iHealthySensorCount <= 1) OR (rSlurryTankLevel_Pct < 5.0) THEN
            iState := 50; (* Degraded fallback *)
        END_IF;

    30: (* STATE_HIGH_VFA_BUFFER_SURGE: Aggressive restoration of buffering capacity *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0030;
        wAlarmWord.5                := TRUE; (* Acidification surge alert *)
        udiAcidificationEventTotal  := udiAcidificationEventTotal + 1;

        (* Drive slurry dosing to maximum mechanical ceiling *)
        rBufferSlurryDoseRate_Lh    := 980.0;
        rNutrientCircPumpSpeed_Pct  := 55.0;

        IF bAirInjectionPermissive THEN
            rAirInjectionFlow_Nm3h  := (rBiogasFlow_Filt * rH2S_RawGas_ppm * 0.000001 * 2.06 * 1.35);
        ELSE
            rAirInjectionFlow_Nm3h  := 0.0;
        END_IF;

        rCumulativeSlurryDosed_L    := rCumulativeSlurryDosed_L + (rBufferSlurryDoseRate_Lh / 3600.0);

        (* Exit condition: VFA reduced below 3300 mg/L and pH restored above 7.15 *)
        IF (rVolatileFattyAcids_mgL < 3300.0) AND (rVotedDigesterPh >= 7.15) THEN
            wAlarmWord.5 := FALSE;
            iState := 20; (* Return to Normal State *)
        ELSIF rVotedDigesterPh < 6.50 THEN
            (* Runaway acidification: Graceful fallback *)
            iState := 50;
        END_IF;

    40: (* STATE_H2S_SCRUBBER_DESULF_PEAK: Breakthrough gas scrubbing management *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0040;
        wAlarmWord.6                := TRUE; (* Scrubber breakthrough alert *)

        (* Maximize biofilm contact via 100% recirculation wash *)
        rNutrientCircPumpSpeed_Pct  := 100.0;

        IF bAirInjectionPermissive THEN
            rAirInjectionFlow_Nm3h  := 120.0; (* Maximum permissible safe micro-aeration *)
        ELSE
            rAirInjectionFlow_Nm3h  := 0.0;
        END_IF;

        rBufferSlurryDoseRate_Lh    := 120.0;

        (* If outlet H2S exceeds safety limits for gas engines (>400 ppm), divert partial stream to flare *)
        IF rH2SClean_Filt > 400.0 THEN
            rBiogasBypassValve_Pct  := 45.0;
        ELSE
            rBiogasBypassValve_Pct  := 0.0;
        END_IF;

        IF rH2SClean_Filt < 70.0 THEN
            wAlarmWord.6            := FALSE;
            rBiogasBypassValve_Pct  := 0.0;
            iState                  := 20;
        END_IF;

    50: (* STATE_DEGRADED_FAILSAFE_FALLBACK: Redundancy loss or chemical starvation *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0050;
        wAlarmWord.7                := TRUE; (* Degraded operation status active *)

        (* Safe open-loop proportioning based on inflow *)
        IF rSlurryTankLevel_Pct >= 3.0 THEN
            rBufferSlurryDoseRate_Lh := (rBiogasFlow_Filt / 5000.0) * 220.0;
        ELSE
            rBufferSlurryDoseRate_Lh := 0.0;
            wAlarmWord.8 := TRUE;            (* Slurry tank empty interlock *)
        END_IF;

        IF bAirInjectionPermissive THEN
            rAirInjectionFlow_Nm3h := (rBiogasFlow_Filt / 5000.0) * 30.0;
        ELSE
            rAirInjectionFlow_Nm3h := 0.0;
        END_IF;

        rNutrientCircPumpSpeed_Pct := 60.0;
        rBiogasBypassValve_Pct     := 0.0;

        IF (iHealthySensorCount >= 2) AND (rSlurryTankLevel_Pct >= 18.0) AND bAutoModeSelect THEN
